#include <iostream>
using namespace std;
const int M=10;
void read(double a[M][M],int r,int c){for(int i=0;i<r;i++)for(int j=0;j<c;j++)if(!(cin>>a[i][j]))throw 1;}
void print(double a[M][M],int r,int c){for(int i=0;i<r;i++){for(int j=0;j<c;j++)cout<<a[i][j]<<"\t";cout<<"\n";}}
double det(double a[M][M],int n){if(n==1)return a[0][0];if(n==2)return a[0][0]*a[1][1]-a[0][1]*a[1][0];double d=0,b[M][M];for(int x=0;x<n;x++){int rr=0;for(int i=1;i<n;i++){int cc=0;for(int j=0;j<n;j++)if(j!=x)b[rr][cc++]=a[i][j];rr++;}d+=(x%2?-1:1)*a[0][x]*det(b,n-1);}return d;}
int main(){double a[M][M],b[M][M],z[M][M];int ch,r,c,s,t;do{cout<<"\n1.Add 2.Multiply 3.Transpose 4.Determinant 0.Exit\n";if(!(cin>>ch))return 1;if(ch==1||ch==2){cout<<"A rows columns: ";if(!(cin>>r>>c)||r<1||r>M||c<1||c>M)return 1;read(a,r,c);cout<<"B rows columns: ";if(!(cin>>s>>t)||s<1||s>M||t<1||t>M)return 1;read(b,s,t);if(ch==1){if(r!=s||c!=t){cout<<"Dimensions must match\n";continue;}for(int i=0;i<r;i++)for(int j=0;j<c;j++)z[i][j]=a[i][j]+b[i][j];print(z,r,c);}else{if(c!=s){cout<<"Incompatible dimensions\n";continue;}for(int i=0;i<r;i++)for(int j=0;j<t;j++){z[i][j]=0;for(int k=0;k<c;k++)z[i][j]+=a[i][k]*b[k][j];}print(z,r,t);}}else if(ch==3){cout<<"Rows columns: ";if(!(cin>>r>>c)||r<1||r>M||c<1||c>M)return 1;read(a,r,c);for(int j=0;j<c;j++){for(int i=0;i<r;i++)cout<<a[i][j]<<"\t";cout<<"\n";}}else if(ch==4){cout<<"Order: ";if(!(cin>>r)||r<1||r>M)return 1;read(a,r,r);cout<<"Determinant = "<<det(a,r)<<"\n";}}while(ch!=0);return 0;}